def h_flip(grid):
    return [row[::-1] for row in grid]

def v_flip(grid):
    return grid[::-1][:]

def rot_90(grid):
    n = len(grid)
    return [[grid[n-1-r][c] for r in range(n)] for c in range(n)]

def rot_180(grid):
    n = len(grid)
    return [[grid[n-1-r][n-1-c] for c in range(n)] for r in range(n)]

def rot_270(grid):
    n = len(grid)
    return [[grid[r][n-1-c] for r in range(n)] for c in range(n)]

def diag_transpose(grid):
    n = len(grid)
    return [[grid[j][i] for j in range(n)] for i in range(n)]

def anti_diag_transpose(grid):
    n = len(grid)
    return [[grid[n-1-j][n-1-i] for j in range(n)] for i in range(n)]

