def check_transformations(blobs, name):
    print(f"\n{name}:")

    for name_op, op in [("H flip", h_flip), ("V flip", v_flip), ("Rot90", rot_90), 
                       ("Rot180", rot_180), ("Rot270", rot_270), ("DiagT", diag_transpose), ("AntiT", anti_diag_transpose)]:
        result = []
        for b in blobs:
            result.append(op(b))

        # Check if all results match originals
        match = all(result[i] == blobs[i] for i in range(len(blobs)))
        if match:
            print(f"  {op} matches ALL blobs!")
        else:
            # Show each transform
            for i, (orig, tr) in enumerate(zip(blobs, result)):
                if orig != tr:
                    print(f"  {name_op} for blob{i} differs:")
                    print(f"    {orig}")
                    print(f"    {tr}")

